<script lang="ts">
	import { onMount } from "svelte";
	import { Button } from "$lib/components/ui/button";
	import * as Card from "$lib/components/ui/card";
	import { createMood, deleteMood, listMood, moodStatistics, updateMood, type MoodEntry, type MoodRange, type MoodStatistics } from "$lib/api/mood";

	const ranges: { value: MoodRange; label: string }[] = [{ value: "today", label: "Today" }, { value: "last7", label: "Last 7 days" }, { value: "last30", label: "Last 30 days" }, { value: "all", label: "All time" }];
	let score = $state(3); let note = $state(""); let entries = $state<MoodEntry[]>([]); let nextCursor = $state<string | null>(null); let statistics = $state<MoodStatistics | null>(null); let range = $state<MoodRange>("all"); let error = $state(""); let editing = $state<number | null>(null);
	const date = (iso: string) => new Date(iso).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
	async function load() { error = ""; try { const [history, data] = await Promise.all([listMood(range), moodStatistics(range)]); entries = history.items; nextCursor = history.next_cursor; statistics = data; } catch (cause) { error = cause instanceof Error ? cause.message : "Could not load mood data"; } }
	async function loadMore() { if (!nextCursor) return; try { const page = await listMood(range, nextCursor); entries = [...entries, ...page.items]; nextCursor = page.next_cursor; } catch (cause) { error = cause instanceof Error ? cause.message : "Could not load more mood history"; } }
	async function save() { try { if (editing === null) await createMood(score, note); else await updateMood(editing, score, note); note = ""; score = 3; editing = null; await load(); } catch (cause) { error = cause instanceof Error ? cause.message : "Could not save mood"; } }
	function edit(entry: MoodEntry) { editing = entry.id; score = entry.score; note = entry.note ?? ""; }
	async function remove(id: number) { if (confirm("Permanently delete this mood entry?")) { try { await deleteMood(id); await load(); } catch (cause) { error = cause instanceof Error ? cause.message : "Could not delete mood"; } } }
	function selectRange(value: MoodRange) { range = value; void load(); }
	onMount(load);
</script>

<main class="mx-auto min-h-screen w-full max-w-3xl px-4 py-10">
	<header class="mb-8 flex items-baseline justify-between"><h1 class="text-3xl font-semibold tracking-tight">Mood tracker</h1><Button variant="outline" size="sm" onclick={() => (window.location.href = "/history")}>Timeline</Button></header>
	<Card.Root class="mb-8"><Card.Header><Card.Title>{editing === null ? "How are you feeling?" : "Edit mood entry"}</Card.Title></Card.Header><Card.Content class="space-y-4"><div class="flex gap-2" aria-label="Mood score">{#each [1, 2, 3, 4, 5] as value}<Button variant={score === value ? "default" : "outline"} onclick={() => (score = value)}>{value}</Button>{/each}</div><label class="block text-sm font-medium" for="mood-note">Note (optional)</label><textarea id="mood-note" class="min-h-28 w-full rounded-md border bg-background p-3" bind:value={note} maxlength="10000" placeholder="What is on your mind?"></textarea><div class="flex gap-2"><Button onclick={save}>{editing === null ? "Save mood" : "Save changes"}</Button>{#if editing !== null}<Button variant="outline" onclick={() => { editing = null; note = ""; score = 3; }}>Cancel</Button>{/if}</div></Card.Content></Card.Root>
	{#if error}<p class="mb-4 text-destructive">{error}</p>{/if}
	<div class="mb-5 flex flex-wrap gap-2" aria-label="Mood range">{#each ranges as option}<Button variant={range === option.value ? "default" : "outline"} size="sm" onclick={() => selectRange(option.value)}>{option.label}</Button>{/each}</div>
	{#if statistics}<section class="mb-8" aria-labelledby="analytics"><h2 id="analytics" class="mb-3 text-xl font-semibold">Mood insights</h2>{#if statistics.entry_count === 0}<p class="text-muted-foreground">No mood entries in this range yet.</p>{:else}<div class="grid grid-cols-2 gap-3"><Card.Root><Card.Content class="p-4"><p class="text-sm text-muted-foreground">Entries</p><p class="text-2xl font-semibold">{statistics.entry_count}</p></Card.Content></Card.Root><Card.Root><Card.Content class="p-4"><p class="text-sm text-muted-foreground">Average mood</p><p class="text-2xl font-semibold">{statistics.average_score?.toFixed(1)}</p></Card.Content></Card.Root></div><h3 class="mt-5 font-medium">Score distribution</h3><div class="mt-2 space-y-2" role="img" aria-label="Mood score distribution">{#each statistics.distribution as count, index}<div><div class="flex justify-between text-sm"><span>{index + 1}/5</span><span>{count} {count === 1 ? "entry" : "entries"} ({statistics.distribution_percentages[index].toFixed(0)}%)</span></div><div class="h-3 rounded bg-muted"><div class="h-3 rounded bg-primary" style={`width: ${statistics.distribution_percentages[index]}%`}></div></div></div>{/each}</div><h3 class="mt-5 font-medium">Daily trend</h3><svg class="mt-2 h-32 w-full" viewBox="0 0 100 50" role="img" aria-label="Daily average mood trend">{#if statistics.trend.length > 1}<polyline fill="none" stroke="currentColor" stroke-width="2" points={statistics.trend.map((point, index) => `${(index * 100) / (statistics.trend.length - 1)},${50 - ((point.average_score - 1) * 50) / 4}`).join(" ")}></polyline>{:else if statistics.trend.length === 1}<circle cx="50" cy={50 - ((statistics.trend[0].average_score - 1) * 50) / 4} r="3" fill="currentColor"></circle>{/if}</svg><ul class="sr-only">{#each statistics.trend as point}<li>{point.date}: {point.average_score.toFixed(1)}</li>{/each}</ul>{/if}</section>{/if}
	<section aria-labelledby="history"><h2 id="history" class="mb-3 text-xl font-semibold">Mood history</h2>{#if entries.length === 0}<p class="text-muted-foreground">Your mood history will appear here.</p>{:else}<div class="space-y-3">{#each entries as entry}<Card.Root><Card.Content class="p-4"><div class="flex items-start justify-between gap-4"><div><p class="font-semibold">Mood {entry.score}/5</p><p class="text-sm text-muted-foreground">{date(entry.recorded_at)}</p>{#if entry.note}<p class="mt-2 whitespace-pre-wrap">{entry.note}</p>{/if}</div><div class="flex gap-2"><Button size="sm" variant="outline" onclick={() => edit(entry)}>Edit</Button><Button size="sm" variant="destructive" onclick={() => remove(entry.id)}>Delete</Button></div></div></Card.Content></Card.Root>{/each}{#if nextCursor}<Button class="mt-4" variant="outline" onclick={loadMore}>Load more mood history</Button>{/if}</div>{/if}</section>
</main>
